
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_sregtm_v1_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_sregtm_v1", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.654435848393430e+00, -4.561771485722245e+00, -4.431993026475795e+00, -4.252359150135824e+00, -4.007887704909140e+00, -3.683164096701831e+00, -3.266591644548701e+00, -2.757925955634470e+00, -2.177585330720507e+00, -1.568707740592405e+00, -1.009326003418667e+00, -7.071790718389546e-01, -6.027047535097692e-01, -5.110913186330953e-01, -3.670548780416947e-01, -2.263310216756013e-01, -1.198003160957424e-01, -5.402433244082255e-02, -2.012346857665292e-02, -5.340788267129101e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


